const updateProduct = `-- name: UpdateProduct :one
UPDATE products
SET slug = $2, title = $3, description = $4, active = $5,
    option1_name = $6, option2_name = $7, option3_name = $8, updated_at = now()
WHERE id = $1
RETURNING id, slug, title, description, image_key, option1_name, option2_name, option3_name, active, created_at, updated_at, search
`

type UpdateProductParams struct {
	ID          string
	Slug        string
	Title       string
	Description string
	Active      bool
	Option1Name string
	Option2Name string
	Option3Name string
}

// updated_at is maintained here rather than by a trigger, so the write is visible
// in the query itself.
//
// image_key does not appear here: the product form does not touch the image, and an
// image is only ever set by SetProductImage or cleared by ClearProductImage. That is
// what makes a submission from a form with no image field harmless, rather than a
// silent way to blank the picture.
func (q *Queries) UpdateProduct(ctx context.Context, arg UpdateProductParams) (Product, error) {
	row := q.db.QueryRow(ctx, updateProduct,
		arg.ID,
		arg.Slug,
		arg.Title,
		arg.Description,
		arg.Active,
		arg.Option1Name,
		arg.Option2Name,
		arg.Option3Name,
	)
	var i Product
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.Title,
		&i.Description,
		&i.ImageKey,
		&i.Option1Name,
		&i.Option2Name,
		&i.Option3Name,
		&i.Active,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Search,
	)
	return i, err
}

