const upsertCategory = `-- name: UpsertCategory :one
INSERT INTO categories (id, slug, name, position)
VALUES (gen_random_uuid(), $1, $2, $3)
ON CONFLICT (slug) DO UPDATE SET slug = EXCLUDED.slug
RETURNING id, slug, name, position
`

type UpsertCategoryParams struct {
	Slug     string
	Name     string
	Position int
}

// ON CONFLICT DO UPDATE rather than DO NOTHING, because DO NOTHING returns no row
// on conflict and the caller needs the id either way. slug = EXCLUDED.slug is a
// write of the value that is already there; name and position are deliberately
// left alone, so re-seeding never overwrites a category the operator has renamed
// or reordered.
func (q *Queries) UpsertCategory(ctx context.Context, arg UpsertCategoryParams) (Category, error) {
	row := q.db.QueryRow(ctx, upsertCategory, arg.Slug, arg.Name, arg.Position)
	var i Category
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.Name,
		&i.Position,
	)
	return i, err
}

const upsertProduct = `-- name: UpsertProduct :one
INSERT INTO products (id, slug, title, description, active,
                      option1_name, option2_name, option3_name)
VALUES (gen_random_uuid(), $1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (slug) DO UPDATE
SET title = EXCLUDED.title, description = EXCLUDED.description,
    active = EXCLUDED.active, option1_name = EXCLUDED.option1_name,
    option2_name = EXCLUDED.option2_name, option3_name = EXCLUDED.option3_name,
    updated_at = now()
RETURNING id, slug, title, description, image_key, option1_name, option2_name, option3_name, active, created_at, updated_at, search
`

type UpsertProductParams struct {
	Slug        string
	Title       string
	Description string
	Active      bool
	Option1Name string
	Option2Name string
	Option3Name string
}

// Upserts by natural key — slug for a product, SKU for a variant — which is what
// makes cmd/seed rerunnable.
// No image column here either, so a seed file cannot claim a product's image: a
// fixture has no way to upload bytes. Re-seeding leaves an uploaded image alone.
func (q *Queries) UpsertProduct(ctx context.Context, arg UpsertProductParams) (Product, error) {
	row := q.db.QueryRow(ctx, upsertProduct,
		arg.Slug,
		arg.Title,
		arg.Description,
		arg.Active,
		arg.Option1Name,
		arg.Option2Name,
		arg.Option3Name,
	)
	var i Product
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.Title,
		&i.Description,
		&i.ImageKey,
		&i.Option1Name,
		&i.Option2Name,
		&i.Option3Name,
		&i.Active,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Search,
	)
	return i, err
}

